import React from 'react';
import { Container, Row, Col, Card } from 'react-bootstrap';
import { FaGraduationCap, FaBook, FaUniversity, FaChartLine, FaFlask, FaNetworkWired, FaMicroscope, FaLaptopCode } from 'react-icons/fa';

const Home = () => {
    const concours = [
        {
            id: 1,
            title: 'Concours Polytechnique',
            description: 'Préparation aux concours des écoles d\'ingénieurs polytechniques',
            icon: <FaFlask />,
        },
        {
            id: 2,
            title: 'ENPT',
            description: 'Préparation au concours de l\'École Nationale des Postes et Télécommunications',
            icon: <FaNetworkWired />,
        },
        {
            id: 3,
            title: 'Concours Paramédicaux',
            description: 'Formation pour les concours du secteur médical et paramédical',
            icon: <FaMicroscope />,
        },
        {
            id: 4,
            title: 'Concours Informatique',
            description: 'Préparation aux concours des écoles d\'ingénieurs en informatique',
            icon: <FaLaptopCode />,
        },
    ];

    return (
        <div>
            {/* Hero Section */}
            <section className="hero-section text-center">
                <Container>
                    <h1>Préparation aux Concours</h1>
                    <p className="lead">
                        Une formation complète et personnalisée pour réussir vos concours
                    </p>
                </Container>
            </section>

            {/* Concours Section */}
            <section className="py-5">
                <Container>
                    <h2 className="text-center section-title">Nos Formations</h2>
                    <Row>
                        {concours.map((concour) => (
                            <Col key={concour.id} md={6} lg={3}>
                                <Card className="h-100 text-center">
                                    <Card.Body>
                                        <div className="icon-container">
                                            {concour.icon}
                                        </div>
                                        <Card.Title>{concour.title}</Card.Title>
                                        <Card.Text>{concour.description}</Card.Text>
                                    </Card.Body>
                                </Card>
                            </Col>
                        ))}
                    </Row>
                </Container>
            </section>
        </div>
    );
};

export default Home;
